class MainActivity:Activity(),SensorEventListener{
    private lateinit var store:Store;private lateinit var feedback:Feedback;private lateinit var root:LinearLayout;private lateinit var page:LinearLayout
    private var tab="Practice";private var screen="main";private var selected=Presets.listening;private var prePulse:Int?=null
    private val ui=Handler(Looper.getMainLooper());private var signature="";private var timer:TextView?=null;private var elapsed:TextView?=null;private var dial:Dial?=null;private var playerLabel:TextView?=null;private var seek:SeekBar?=null;private var dragging=false;private var dim=false
    private var chartDays=30;private var morning=false;private var diaryFilter="All";private var diaryLimit=75;private var exportPending:ByteArray?=null
    private var walking=false;private var holding=false;private var walkStart=0L;private var holdStart=0L;private var walkDate=0L;private var walkId="";private var steps=0;private var totalSteps=0;private var reference=5;private var sensor=false;private var walkSource="Manual";private val rounds=mutableListOf<WalkValue>();private var stepLabel:TextView?=null;private var walkTime:TextView?=null
    private val tick=object:Runnable{override fun run(){val s=PracticeService.live;val e=s?.engine
        if(screen=="timer"){
            if(s?.ending==true && PracticeService.lastResult!=null){val id=PracticeService.lastResult!!;PracticeService.lastResult=null;screen="main";tab="Diary";dim=false;renderMain();editEntry(store.entries.firstOrNull{it.id==id})}
            else if(e!=null){val sig="${e.index}/${e.state}/${e.interrupted}/$dim";if(sig!=signature){signature=sig;renderTimer()};val now=SystemClock.elapsedRealtime();timer?.text=when(e.state){State.CP_READY->"Ready";State.CP_RUNNING->if(store.bool("hideCp"))"CP running"else"%.1f s".format(e.cpElapsed(now));State.CP_REVIEW->"%.1f s".format(e.pendingCp);State.LISTENING->clock((s.audioDuration-s.audioPosition).coerceAtLeast(0)/1000L);State.FINISHED->"Finished";else->if(e.phase.kind==Kind.LISTEN)clock((s.audioDuration-s.audioPosition).coerceAtLeast(0)/1000L)else clock((e.remaining(now)+999)/1000)};elapsed?.text="Phase ${e.index+1} / ${e.protocol.phases.size} · ${clock(e.total(now).toLong())} practiced";dial?.progress=when(e.phase.kind){Kind.CP->0f;Kind.LISTEN->s.audioPosition.toFloat()/s.audioDuration.coerceAtLeast(1);else->1f-e.remaining(now).toFloat()/(e.phase.seconds*1000L).coerceAtLeast(1)};if(e.phase.kind==Kind.LISTEN){playerLabel?.text="${clock(s.audioPosition/1000L)} / ${clock(s.audioDuration/1000L)}";if(!dragging)seek?.progress=s.audioPosition}}
        }
        if(walking){val now=SystemClock.elapsedRealtime();stepLabel?.text=(if(holding)steps else totalSteps).toString();walkTime?.text=if(holding)"${"%.1f".format((now-holdStart)/1000.0)} s"else clock((now-walkStart)/1000);if(holding && now-holdStart>=60000){endHold();toast("Hold stopped at the software limit. Breathe normally.")};if(now-walkStart>=12*60000){finishWalk();toast("Walking session finished")}}
        PracticeService.failure?.let{PracticeService.failure=null;toast(it)};ui.postDelayed(this,250)
    }}
    override fun onCreate(state:Bundle?){super.onCreate(state);store=Store.get(this);feedback=Feedback(this);if(PracticeService.live==null)safe{if(store.recover())toast("Interrupted session recovered in the diary")};if(PracticeService.live!=null){screen="timer";renderTimer()}else renderMain();if(!store.bool("safetyAccepted",false))welcome();store.error?.let{toast(it)}}
    override fun onResume(){super.onResume();ui.removeCallbacks(tick);ui.post(tick)}
    override fun onPause(){ui.removeCallbacks(tick);super.onPause()}
    override fun onStop(){PracticeService.live?.backgroundCp();if(walking)finishWalk();super.onStop()}
    override fun onDestroy(){ui.removeCallbacks(tick);feedback.release();stopSensor();super.onDestroy()}
    override fun onNewIntent(i:Intent){super.onNewIntent(i);if(PracticeService.live?.ending==false){screen="timer";signature="";renderTimer()}}
    override fun onBackPressed(){when(screen){"main"->super.onBackPressed();"walking"->if(walking)ask("End walking session?","Recorded rounds will be saved."){finishWalk()}else{screen="main";renderMain()};else->{PracticeService.live?.backgroundCp();screen="main";dim=false;renderMain()}}}
    override fun onKeyDown(key:Int,event:KeyEvent):Boolean{if(store.bool("volumeKeys",false) && screen=="timer" && key in listOf(KeyEvent.KEYCODE_VOLUME_UP,KeyEvent.KEYCODE_VOLUME_DOWN)){if(event.repeatCount==0){val s=PracticeService.live;if(key==KeyEvent.KEYCODE_VOLUME_UP)s?.remotePrimary()else if(s?.engine?.state==State.CP_REVIEW)s.review(false)else if(s?.engine?.state==State.CP_RUNNING)s.stopCp()else s?.pause()};return true};return super.onKeyDown(key,event)}
    private fun dp(n:Int)=(n*resources.displayMetrics.density).roundToInt()
    private fun clock(s:Long)=PracticeService.clock(s)
    private fun date(t:Long)=SimpleDateFormat("EEE d MMM · HH:mm",Locale.getDefault()).format(Date(t))
    private fun toast(t:String)=Toast.makeText(this,t,Toast.LENGTH_LONG).show()
    private fun safe(block:()->Unit){try{block()}catch(e:Exception){AlertDialog.Builder(this).setTitle("Action could not be completed").setMessage(e.message ?:"Please try again").setPositiveButton("Close",null).show()}}
    private fun ask(title:String,message:String,action:()->Unit){AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->safe(action)}.show()}
    private fun txt(t:String,size:Float=15f,color:Int=P.text,bold:Boolean=false)=TextView(this).apply{text=t;textSize=size;setTextColor(color);setLineSpacing(dp(3).toFloat(),1.03f);if(bold)typeface=Typeface.create("sans-serif-medium",0)}
    private fun label(parent:LinearLayout,t:String,size:Float=15f,color:Int=P.text,bold:Boolean=false):TextView{val v=txt(t,size,color,bold);parent.addView(v);return v}
    private fun gap(n:Int=12,parent:LinearLayout=page){parent.addView(View(this),LinearLayout.LayoutParams(1,dp(n)))}
    private fun panel(parent:LinearLayout=page)=LinearLayout(this).apply{orientation=1;setPadding(dp(18),dp(17),dp(18),dp(17));background=P.shape(P.panel,dp(18).toFloat(),P.line);parent.addView(this,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(12)})}
    private fun row(parent:LinearLayout=page)=LinearLayout(this).apply{orientation=0;gravity=Gravity.CENTER_VERTICAL;parent.addView(this,LinearLayout.LayoutParams(-1,-2))}
    private fun button(t:String,parent:LinearLayout=page,primary:Boolean=false,action:()->Unit):Button=Button(this).apply{text=t;isAllCaps=false;textSize=14f;setTextColor(if(primary)P.text else P.accent);background=P.shape(if(primary)P.button else P.panel,dp(13).toFloat(),P.line);minHeight=dp(52);setPadding(dp(12),dp(9),dp(12),dp(9));parent.addView(this,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(7);bottomMargin=dp(3)});setOnClickListener{safe(action)}}
    private fun field(parent:LinearLayout,name:String,value:String="",number:Boolean=false):EditText{label(parent,name,12f,P.muted);return EditText(this).apply{setText(value);hint=name;textSize=16f;setTextColor(P.text);setHintTextColor(P.muted);inputType=if(number)InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL else InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_FLAG_CAP_SENTENCES;setPadding(dp(7),dp(9),dp(7),dp(9));parent.addView(this,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(9)})}}
    private fun note(t:String){val c=panel();label(c,t,13f,P.muted)}
    private fun heading(t:String,sub:String=""){label(page,t,30f,P.text,true);if(sub.isNotBlank()){gap(8);label(page,sub,14f,P.muted)};gap(21)}
    private fun base(nav:Boolean=true){window.statusBarColor=P.bg;window.navigationBarColor=P.bg;window.decorView.systemUiVisibility=0;if(Build.VERSION.SDK_INT>=30)window.setDecorFitsSystemWindows(false)
        window.attributes=window.attributes.apply{screenBrightness=max(.02f,store.int("brightness",12)/100f)}
        if((screen=="timer" && store.bool("screenOn",false)) || screen=="walking")window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)else window.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        root=LinearLayout(this).apply{orientation=1;setBackgroundColor(P.bg);setOnApplyWindowInsetsListener{v,i->if(Build.VERSION.SDK_INT>=30){val b=i.getInsets(WindowInsets.Type.systemBars() or WindowInsets.Type.ime());v.setPadding(b.left,b.top,b.right,b.bottom)}else v.setPadding(0,i.systemWindowInsetTop,0,i.systemWindowInsetBottom);i}}
        val scroll=ScrollView(this).apply{isFillViewport=true;isVerticalScrollBarEnabled=false;setBackgroundColor(P.bg)};page=LinearLayout(this).apply{orientation=1;setPadding(dp(21),dp(18),dp(21),dp(28))};scroll.addView(page);root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))
        if(nav){val bar=row(root);bar.setPadding(dp(4),dp(7),dp(4),dp(6));listOf("Practice","Diary","Trends","Learn","Settings").forEach{t->bar.addView(TextView(this).apply{text=t;textSize=11f;gravity=Gravity.CENTER;minHeight=dp(48);setTextColor(if(tab==t)P.accent else P.muted);if(tab==t)background=P.shape(P.panel,dp(10).toFloat());isFocusable=true;contentDescription=t;setOnClickListener{tab=t;screen="main";renderMain()}},LinearLayout.LayoutParams(0,-2,1f))}}
        setContentView(root);root.requestApplyInsets()
    }
    private fun renderMain(){base();when(tab){"Practice"->practice();"Diary"->diary();"Trends"->trends();"Learn"->learn();else->settings()}}
    private fun practice(){heading("Upekkhā","Practice, measurements and session notes.")
        val s=PracticeService.live;if(s!=null && !s.ending){val c=panel();label(c,"Session in progress",12f,P.accent);label(c,s.engine?.protocol?.name ?:"Practice",20f,P.text,true);button("Return to session",c,true){screen="timer";signature="";renderTimer()}}
        val recent=store.str("lastProtocol","");val all=Presets.all+store.protocols;all.find{it.id==recent}?.let{p->button("Repeat ${p.name}",primary=true){preview(p)}}
        gap(12);val audio=panel();label(audio,"Audio practice",12f,P.accent);gap(7,audio);label(audio,"Mindfulness Buteyko",23f,P.text,true);label(audio,"Marilleke Vrancken · 20:27",14f,P.muted);gap(10,audio);label(audio,"5 min rest · CP · recording · 5 min recovery · 5 min wait · CP",13f,P.muted);button("Open audio practice",audio,true){preview(Presets.listening)}
        val values=store.entries.flatMap{it.cps}.filter{it.valid}.sortedByDescending{it.timestamp};val week=values.filter{it.timestamp>=System.currentTimeMillis()-7*86400000L};val metrics=row();for((v,k)in listOf((values.firstOrNull()?.let{"%.1f s".format(it.seconds)} ?:"—") to "Latest CP",(if(week.isEmpty())"—"else"%.1f s".format(week.map{it.seconds}.average())) to "7-day average")){val c=LinearLayout(this).apply{orientation=1;setPadding(dp(12),dp(15),dp(8),dp(15))};metrics.addView(c,LinearLayout.LayoutParams(0,-2,1f));label(c,v,24f);label(c,k,12f,P.muted)};gap(15)
        val favorites=all.filter{store.favorite(it.id)};if(favorites.isNotEmpty()){label(page,"Favourites",19f,P.text,true);gap(8);favorites.forEach{protocolCard(it)}}
        label(page,"Protocols",19f,P.text,true);gap(10);all.filter{it.id!="mindfulness"}.forEach{protocolCard(it)}
        button("Create protocol"){editor(null)};button("Walking practice"){walkSetup()}
    }
    private fun protocolCard(p:Protocol){val c=panel();label(c,p.name,20f,P.text,true);gap(5,c);label(c,"${p.durationSeconds/60} min timed · ${p.cpCount} CP${if(p.custom)" · custom"else""}",12f,P.accent);gap(7,c);label(c,p.description,13f,P.muted);button("Open",c){preview(p)}}
    private fun preview(p:Protocol){selected=p;prePulse=null;screen="preview";base(false);button("Back"){screen="main";renderMain()};gap(18);heading(p.name,p.description)
        if(p.phases.any{it.kind==Kind.LISTEN})note("CP is measured after the initial rest. When the recording finishes, recovery runs for five minutes, followed by a further five-minute wait before the second CP. Edit either interval below if your routine differs.")
        p.phases.forEachIndexed{i,phase->val c=panel();label(c,"${i+1}. ${phase.title}",18f,P.text,true);label(c,if(phase.kind==Kind.CP)"User-controlled"else clock(phase.seconds.toLong()),13f,P.accent);gap(7,c);label(c,phase.guidance,13f,P.muted)}
        button(if(store.favorite(p.id))"Remove from favourites"else"Add to favourites"){store.toggleFavorite(p.id);preview(p)}
        button("Record pulse before starting"){pulseDialog{prePulse=it;toast("Pulse saved for this session: $it bpm")}}
        if(store.bool("pulsePrompt",false))note("Pulse reminder: you can record a resting value before starting and another during the session.")
        button("Start session",primary=true){start(p)};button(if(p.custom)"Edit protocol"else"Edit a copy"){editor(p)}
        if(p.custom)button("Delete protocol"){ask("Delete protocol?","Diary entries are kept."){store.protocols.removeAll{it.id==p.id};store.save();screen="main";renderMain()}}
    }
    private fun start(p:Protocol){check(!walking){"Finish the walking session first"};PracticeService.live?.let{check(!it.ending){"The previous session is finishing. Please wait two seconds."};screen="timer";renderTimer();return};check(store.error==null){store.error ?:"Saved data unavailable"};if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),40);val i=Intent(this,PracticeService::class.java).setAction("START").putExtra("protocol",Codec.protocol(p).toString());prePulse?.let{i.putExtra("pulse",it)};PracticeService.lastResult=null;startForegroundService(i);screen="timer";signature="";dim=false;renderTimer()}
    private fun renderTimer(){base(false);val s=PracticeService.live;val e=s?.engine;if(e==null){heading("Starting session");button("Back"){screen="main";renderMain()};return}
        if(!dim){button("Practice home"){PracticeService.live?.backgroundCp();screen="main";renderMain()};gap(14);label(page,e.protocol.name,13f,P.muted);gap(8);heading(e.phase.title)}else{gap(25);label(page,e.phase.title,22f,P.muted);gap(20)}
        elapsed=label(page,"",12f,P.muted);dial=Dial(this);if(!dim)page.addView(dial,LinearLayout.LayoutParams(-1,dp(110)))
        timer=label(page,"",if(dim)34f else 44f,if(dim)P.muted else P.text,true).apply{gravity=Gravity.CENTER};gap(18)
        if(!dim){label(page,e.phase.guidance,15f,P.muted);gap(14);if(s.note.isNotBlank())note(s.note)}
        when(e.state){
            State.CP_READY->{if(!dim)note("Start after an ordinary exhalation. Breathe at the first urge, even if the clock is hidden.");button("Start CP",primary=true){s.startCp();renderTimer()};if(!dim)button("Skip CP"){s.skip();renderTimer()}}
            State.CP_RUNNING->{button("Stop CP · breathe now",primary=true){s.stopCp();renderTimer()}.minHeight=dp(86);if(!dim)label(page,"End at the first clear urge to breathe.",14f,P.muted)}
            State.CP_REVIEW->{if(!dim)note(if(e.interrupted)"Interrupted measurement. It will be excluded from trends."else"Was the next breath easy and natural? Exclude this measurement if you needed a deeper or gasping breath.");if(!e.interrupted)button("Keep CP and continue",primary=true){s.review(true);renderTimer()};button("Exclude CP and continue"){s.review(false);renderTimer()}}
            State.PAUSED->{label(page,"Paused",16f,P.muted);button("Resume",primary=true){s.pause();renderTimer()}}
            State.TIMED,State.LISTENING->{button("Pause",primary=true){s.pause();renderTimer()};if(!dim && e.phase.kind!=Kind.LISTEN)button("Skip phase"){ask("Skip this phase?","The next phase begins immediately. CP measurements wait for you to start."){s.skip();renderTimer()}}}
            else->{}
        }
        if(!dim && e.phase.kind==Kind.LISTEN){val c=panel();label(c,"Recording",13f,P.accent);playerLabel=label(c,"",13f,P.muted);seek=SeekBar(this).apply{max=s.audioDuration;progress=s.audioPosition};c.addView(seek);seek!!.setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(v:SeekBar?,p:Int,u:Boolean){};override fun onStartTrackingTouch(v:SeekBar?){dragging=true};override fun onStopTrackingTouch(v:SeekBar?){dragging=false;s.seek(v?.progress ?:0)}});val r=row(c);for((label,delta)in listOf("Back 15 s" to -15000,"Forward 15 s" to 15000)){r.addView(Button(this).apply{text=label;isAllCaps=false;setTextColor(P.accent);setOnClickListener{s.seek(s.audioPosition+delta)}},LinearLayout.LayoutParams(0,dp(50),1f))}}
        button(if(dim)"Show controls"else"Dim view"){dim=!dim;signature="";renderTimer()}
        if(!dim){if(e.state!=State.CP_RUNNING)button("Record pulse"){pulseDialog{s.addPulse(it)}};button("Phase cues"){cuePanel()};if(store.bool("volumeKeys",false))note("Volume up: start/stop CP, keep a result, or pause/resume. Volume down: stop a running CP or exclude a result. These controls work while this screen is open.");if(s.cps.isNotEmpty())note("CP: "+s.cps.joinToString(" · "){"%.1f s%s".format(it.seconds,if(it.valid)""else" (excluded)")});button("End session and save"){ask("End session?","Completed measurements will be saved."){s.finish("Ended early")}}}
    }
    private fun editor(original:Protocol?){screen="editor";var name=original?.let{if(it.custom)it.name else it.name+" custom"} ?:"My protocol";var description=original?.description ?:"";val phases=(original?.phases ?:listOf(Phase(Kind.REST,120),Phase(Kind.CP),Phase(Kind.REDUCE,300),Phase(Kind.RECOVER,300),Phase(Kind.CP))).toMutableList()
        fun draw(){base(false);heading("Edit protocol","Arrange phases and set their lengths in seconds.");val n=field(page,"Name",name);val d=field(page,"Description",description);fun capture(){name=n.text.toString();description=d.text.toString()}
            phases.forEachIndexed{i,p->val c=panel();label(c,"${i+1}. ${p.title}",18f,P.text,true);label(c,if(p.kind==Kind.CP)"User-controlled"else clock(p.seconds.toLong()),13f,P.muted);if(p.kind !in listOf(Kind.CP,Kind.LISTEN))button("Change length",c){capture();val b=LinearLayout(this).apply{orientation=1;setPadding(dp(20),dp(10),dp(20),dp(10))};val f=field(b,"Seconds (5–3600)",p.seconds.toString(),true);val dlg=AlertDialog.Builder(this).setTitle(p.title).setView(b).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();dlg.setOnShowListener{dlg.getButton(-1).setOnClickListener{val v=f.text.toString().toIntOrNull();if(v==null || v !in 5..3600)f.error="Enter 5–3600 whole seconds"else{phases[i]=p.copy(seconds=v);dlg.dismiss();draw()}}};dlg.show()};val actions=row(c);fun small(t:String,a:()->Unit){actions.addView(Button(this).apply{text=t;isAllCaps=false;textSize=12f;setTextColor(P.accent);minWidth=0;setOnClickListener{capture();a();draw()}},LinearLayout.LayoutParams(0,dp(48),1f))};if(i>0)small("Up"){Collections.swap(phases,i,i-1)};if(i<phases.lastIndex)small("Down"){Collections.swap(phases,i,i+1)};small("Remove"){phases.removeAt(i)}}
            button("Add phase"){capture();AlertDialog.Builder(this).setTitle("Phase type").setItems(arrayOf("Rest","Reduced breathing","Recovery","CP","Mindfulness recording")){_,i->if(phases.size<80){val k=Kind.entries[i];phases.add(Phase(k,when(k){Kind.CP->0;Kind.LISTEN->1227;else->60}));draw()}else toast("Maximum 80 phases")}.show()}
            label(page,"${phases.sumOf{it.seconds}/60} timed minutes · ${phases.count{it.kind==Kind.CP}} CP",13f,P.muted)
            button("Save protocol",primary=true){capture();require(name.isNotBlank() && name.length<=100){"Enter a name of 1–100 characters"};val p=Protocol(if(original?.custom==true)original.id else Store.id(),name.trim(),description.trim(),phases.toList(),true);Codec.readProtocol(Codec.protocol(p));store.protocols.removeAll{it.id==p.id};store.protocols.add(p);store.save();screen="main";renderMain()};button("Cancel"){screen="main";renderMain()}
        };draw()
    }
    private fun diary(){heading("Diary","Sessions, CP values, pulse and notes.");button("Add observation"){editEntry(null)};if(store.entries.isEmpty()){note("Sessions are saved here automatically. You can also add an observation without starting a timer.");return};button("Export diary"){exportDialog()};val filters=arrayOf("All","Morning","Audio","Walking");val choose=Spinner(this);choose.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,filters);choose.setSelection(filters.indexOf(diaryFilter).coerceAtLeast(0));page.addView(choose);choose.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onNothingSelected(p:AdapterView<*>?){};override fun onItemSelected(p:AdapterView<*>?,v:View?,i:Int,id:Long){if(diaryFilter!=filters[i]){diaryFilter=filters[i];diaryLimit=75;renderMain()}}};gap(12)
        val entries=store.entries.sortedByDescending{it.timestamp}.filter{when(diaryFilter){"Morning"->it.context=="Morning";"Audio"->it.name.contains("Mindfulness",true) || it.comment.contains("Recording:");"Walking"->it.walks.isNotEmpty();else->true}}
        entries.take(diaryLimit).forEach{e->val c=panel();label(c,date(e.timestamp),12f,P.accent);gap(7,c);label(c,e.name,20f,P.text,true);label(c,"${e.status} · ${clock(e.duration.toLong())} · ${e.context}",12f,P.muted);if(e.cps.isNotEmpty()){gap(9,c);label(c,"CP  "+e.cps.joinToString(" · "){"%.1f s%s".format(it.seconds,if(it.valid)""else" (excluded)")},16f)};if(e.pulses.isNotEmpty())label(c,"Pulse  "+e.pulses.joinToString(" / "){"${it.bpm} bpm"},13f,P.muted);if(e.walks.isNotEmpty())label(c,"Walking  ${e.walks.sumOf{it.steps}} steps in ${e.walks.size} rounds",13f,P.muted);e.symptom?.let{label(c,"Symptom score $it / 10",13f,P.muted)};if(e.comment.isNotBlank()){gap(9,c);label(c,e.comment.take(180)+if(e.comment.length>180)"…"else"",13f,P.muted)};button("Details and notes",c){entryDetails(e)}}
        if(entries.size>diaryLimit)button("Show more entries"){diaryLimit+=75;renderMain()}
    }
    private fun entryDetails(e:Entry){val box=LinearLayout(this).apply{orientation=1;setPadding(dp(22),dp(8),dp(22),dp(15))};label(box,"${date(e.timestamp)}\n${e.status} · ${e.context}\n",14f,P.muted);e.cps.forEach{label(box,"${it.label}: ${"%.1f".format(it.seconds)} s · ${if(it.valid)"valid"else"excluded"}\n${date(it.timestamp)}\n",14f)};e.pulses.forEach{label(box,"${it.label}: ${it.bpm} bpm\n${date(it.timestamp)}\n",14f)};e.walks.forEachIndexed{i,w->label(box,"Round ${i+1}: ${w.steps} steps, ${"%.1f".format(w.seconds)} s (${w.source})",14f)};label(box,"\nSymptom score: ${e.symptom?.toString() ?:"not recorded"}\n\n${e.comment}",14f);val scroll=ScrollView(this);scroll.addView(box);AlertDialog.Builder(this).setTitle(e.name).setView(scroll).setNegativeButton("Close",null).setNeutralButton("Share"){_,_->share(listOf(e),false)}.setPositiveButton("Edit"){_,_->editEntry(e)}.show()}
    private fun editEntry(existing:Entry?){screen="entry";base(false);heading(if(existing==null)"Add observation"else"Session notes");if(existing!=null && existing.cps.isNotEmpty()){val c=panel();label(c,"CP measurements",14f,P.accent);existing.cps.forEach{label(c,"${it.label}: ${"%.1f".format(it.seconds)} s${if(it.valid)""else" (excluded)"}",16f)}};var timestamp=existing?.timestamp ?:System.currentTimeMillis();val dateButton=button(date(timestamp)){};dateButton.setOnClickListener{val c=Calendar.getInstance().apply{timeInMillis=timestamp};DatePickerDialog(this,{_,y,m,d->c.set(y,m,d);TimePickerDialog(this,{_,h,min->c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);timestamp=c.timeInMillis;dateButton.text=date(timestamp)},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show()},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show()};val name=field(page,"Title",existing?.name ?:"Observation");label(page,"Context",12f,P.muted);val contexts=arrayOf("Practice","Morning","Daytime","Evening","After walking","Other");val context=Spinner(this);context.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,contexts);context.setSelection(contexts.indexOf(existing?.context ?:"Practice").coerceAtLeast(0));page.addView(context)
        val cp=if(existing==null)field(page,"CP seconds (optional)","",true)else null;val valid=CheckBox(this).apply{text="Next breath was easy and natural";isChecked=true};if(cp!=null)page.addView(valid)
        val pulse=if(existing==null)field(page,"Pulse bpm (optional)","",true)else null
        val track=Switch(this).apply{text="Record symptom score";isChecked=existing?.symptom!=null};page.addView(track);val score=label(page,"",16f);val symptom=SeekBar(this).apply{max=10;progress=existing?.symptom ?:0;isEnabled=track.isChecked};page.addView(symptom);fun scoreText(){score.text=if(track.isChecked)"Symptoms: ${symptom.progress} / 10"else"Symptoms: not recorded"};scoreText();track.setOnCheckedChangeListener{_,b->symptom.isEnabled=b;scoreText()};symptom.setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,u:Boolean){scoreText()};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){} });label(page,"0 = none · 10 = worst for you. This is a personal scale.",12f,P.muted)
        val notes=field(page,"Notes",existing?.comment ?:"").apply{inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_FLAG_MULTI_LINE or InputType.TYPE_TEXT_FLAG_CAP_SENTENCES;minLines=4;gravity=Gravity.TOP}
        button("Save",primary=true){require(name.text.isNotBlank() && name.text.length<=100){"Enter a title of 1–100 characters"};require(notes.text.length<=10000){"Maximum 10,000 characters in notes"};val n=cp?.text?.toString()?.trim()?.takeIf{it.isNotEmpty()}?.let{it.toDoubleOrNull()?.also{v->require(v.isFinite() && v>0 && v<=600){"CP must be greater than zero and at most 600 seconds"}} ?:error("Invalid CP")};val b=pulse?.text?.toString()?.trim()?.takeIf{it.isNotEmpty()}?.let{it.toIntOrNull()?.also{v->require(v in 20..250){"Pulse must be 20–250 bpm"}} ?:error("Invalid pulse")};val e=existing?.copy(timestamp=timestamp,name=name.text.toString().trim(),context=contexts[context.selectedItemPosition],symptom=if(track.isChecked)symptom.progress else null,comment=notes.text.toString()) ?:Entry(Store.id(),timestamp,name.text.toString().trim(),0,"Observation",if(n!=null)listOf(CpValue(n,timestamp,valid.isChecked,"Manual CP"))else emptyList(),if(b!=null)listOf(PulseValue(b,timestamp,"Manual"))else emptyList(),symptom=if(track.isChecked)symptom.progress else null,comment=notes.text.toString(),context=contexts[context.selectedItemPosition]);store.upsert(e);screen="main";tab="Diary";renderMain()}
        button("Cancel"){screen="main";renderMain()};if(existing!=null)button("Delete entry"){ask("Delete entry?","This removes the entry from this device. Existing backups keep their copy."){store.entries.removeAll{it.id==existing.id};store.save();screen="main";renderMain()}}
    }
    private fun day(t:Long):Long{val c=Calendar.getInstance().apply{timeInMillis=t};return Calendar.getInstance(TimeZone.getTimeZone("UTC")).apply{clear();set(c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH))}.timeInMillis/86400000L}
    private fun trends(){heading("CP trends","Daily averages from valid measurements.");val r=row();for(n in listOf(7,30,90,0)){r.addView(Button(this).apply{text=if(n==0)"All"else"${n}d";isAllCaps=false;setTextColor(if(n==chartDays)P.text else P.muted);background=P.shape(if(n==chartDays)P.button else P.bg,dp(10).toFloat());setOnClickListener{chartDays=n;renderMain()}},LinearLayout.LayoutParams(0,dp(48),1f))};val morningSwitch=Switch(this).apply{text="Morning only";isChecked=morning};page.addView(morningSwitch);morningSwitch.setOnCheckedChangeListener{_,b->morning=b;renderMain()};val today=day(System.currentTimeMillis());val since=if(chartDays==0)Long.MIN_VALUE else today-chartDays+1;val values=store.entries.filter{!morning || it.context=="Morning"}.flatMap{it.cps}.filter{day(it.timestamp) in since..today};val stats=Analysis.stats(values,::day);page.addView(Trend(this,stats?.points ?:emptyList()),LinearLayout.LayoutParams(-1,dp(230)))
        if(stats!=null){val metrics=row();for((name,v)in listOf("Average" to stats.average,"Lowest" to stats.low,"Best" to stats.best)){val c=LinearLayout(this).apply{orientation=1;setPadding(dp(7),dp(15),dp(6),dp(15))};metrics.addView(c,LinearLayout.LayoutParams(0,-2,1f));label(c,"%.1f s".format(v),22f);label(c,name,12f,P.muted)};val change=stats.change;note(if(change==null)"A trend is shown after measurements on two different days."else"${if(abs(change)<.1)"Steady"else if(change>0)"Increasing"else"Decreasing"} · ${"%+.1f".format(change)} seconds between the earlier and later halves of recorded days. ${stats.count} valid measurements across ${stats.points.size} days.")}else note("No valid CP values in this period.")
        note("Excluded values stay in the diary and are left out of these statistics. Compare measurements taken in similar conditions. CP does not measure CO₂, oxygen levels or overall health.")
    }
    private fun settings(){heading("Settings");val appearance=panel();label(appearance,"Display",20f,P.text,true);slider(appearance,"App brightness","brightness",12,2){applyBrightness()};toggle(appearance,"Keep display on during seated sessions","screenOn",false);toggle(appearance,"Hide running CP time","hideCp",true);toggle(appearance,"Volume keys control the timer","volumeKeys",false);label(appearance,"Headset play/pause also starts and stops CP, keeps a reviewed CP, or pauses/resumes a timed phase. Use Next to exclude a reviewed CP. Headset support depends on the device.",12f,P.muted)
        val cues=panel();label(cues,"Phase signals",20f,P.text,true);toggle(cues,"Sound","sound",true);slider(cues,"Tone volume","cueVolume",45);label(cues,"Tones use Android alarm volume. The recording and ambience use media volume.",12f,P.muted);button("Android sound settings",cues){startActivity(Intent(Settings.ACTION_SOUND_SETTINGS))};button("Configure phase tones",cues){toneSettings()};toggle(cues,"Vibration","haptic",true);choice(cues,"Vibration pattern","vibration",Signals.styles.toTypedArray(),"Double");slider(cues,"Vibration intensity","intensity",55);button("Test vibration",cues){feedback.vibrate();toast(if(!feedback.hasVibrator())"No vibrator is available"else if(!feedback.amplitudeControl())"This phone supports patterns but does not expose amplitude control"else"Vibration test")};label(cues,if(feedback.amplitudeControl())"This phone reports support for vibration intensity control."else"Intensity control is unavailable on this phone. The selected pattern is still used.",12f,P.muted)
        val ambient=panel();label(ambient,"Ambience",20f,P.text,true);choice(ambient,"Sound","ambience",arrayOf("Off","Wind","Fireplace"),"Off"){PracticeService.live?.configureAmbience()};slider(ambient,"Ambience volume","volume",30,0){PracticeService.live?.configureAmbience()};label(ambient,"Ambience is muted while the mindfulness recording plays.",12f,P.muted)
        val practice=panel();label(practice,"Practice",20f,P.text,true);toggle(practice,"Pulse reminder before practice","pulsePrompt",false)
        val data=panel();label(data,"Data",20f,P.text,true);label(data,"${store.entries.size} entries · ${store.protocols.size} custom protocols\nData stays on this device. Exports and backups are unencrypted files you choose where to save.",13f,P.muted);button("Save backup",data){check(PracticeService.live==null && !walking){"Finish the active session first"};exportPending=store.json().toString(2).toByteArray();createDocument("Upekkha-backup-${SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())}.json","application/json")};button("Restore or merge backup",data){check(PracticeService.live==null && !walking){"Finish the active session first"};startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),72)};button("Export diary",data){exportDialog()};button("Notification settings",data){startActivity(Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,packageName))}
        val about=panel();label(about,"Upekkhā 2.1",20f,P.text,true);label(about,"Android 8.0+ · local storage",13f,P.muted);button("Safety information",about){read(Knowledge.articles.first{it.category=="Safety"})};button("Sources and recording credits",about){read(Knowledge.articles.last())};label(about,"Do Not Disturb, output routing and manufacturer battery restrictions can affect phase cues. Test the selected cues on your phone.",12f,P.muted)
    }
    private fun applyBrightness(){window.attributes=window.attributes.apply{screenBrightness=max(.02f,store.int("brightness",12)/100f)}}
    private fun toggle(parent:LinearLayout,t:String,key:String,default:Boolean){val v=Switch(this).apply{text=t;textSize=14f;isChecked=store.bool(key,default);setPadding(0,dp(12),0,dp(12));setTextColor(P.text)};parent.addView(v);v.setOnCheckedChangeListener{_,b->safe{store.settings.put(key,b);store.save()}}}
    private fun slider(parent:LinearLayout,t:String,key:String,default:Int,min:Int=0,changed:()->Unit={}){val l=label(parent,"$t: ${store.int(key,default)}%",13f,P.muted);val s=SeekBar(this).apply{max=100;progress=store.int(key,default)};parent.addView(s);s.setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(v:SeekBar?,p:Int,u:Boolean){val n=p.coerceAtLeast(min);l.text="$t: $n%";if(u){store.settings.put(key,n);if(key=="brightness")applyBrightness()}};override fun onStartTrackingTouch(v:SeekBar?){};override fun onStopTrackingTouch(v:SeekBar?){safe{store.settings.put(key,s.progress.coerceAtLeast(min));store.save();changed()}}})}
    private fun choice(parent:LinearLayout,t:String,key:String,options:Array<String>,default:String,changed:()->Unit={}){label(parent,t,12f,P.muted);val sp=Spinner(this);sp.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,options);sp.setSelection(options.indexOf(store.str(key,default)).coerceAtLeast(0));parent.addView(sp);sp.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onNothingSelected(p:AdapterView<*>?){};override fun onItemSelected(p:AdapterView<*>?,v:View?,i:Int,id:Long){if(store.str(key,default)!=options[i])safe{store.settings.put(key,options[i]);store.save();changed()}}}}
    private fun toneSettings(){screen="tones";base(false);heading("Phase tones","Choose a different sound for each phase, then preview it. Sound and vibration can be enabled separately.");Signals.events.forEachIndexed{i,event->val c=panel();label(c,Signals.labels[i],18f,P.text,true);val current=store.str("tone_$event",Signals.defaultTone(event));val title=Signals.tones.firstOrNull{it.id==current}?.name ?:"Unknown";button("Tone: $title",c){AlertDialog.Builder(this).setTitle(Signals.labels[i]).setSingleChoiceItems(Signals.tones.map{it.name}.toTypedArray(),Signals.tones.indexOfFirst{it.id==current}){dialog,n->safe{store.settings.put("tone_$event",Signals.tones[n].id);store.save();feedback.tone(Signals.tones[n].id);dialog.dismiss();toneSettings()}}.setNegativeButton("Cancel",null).show()};button("Preview tone",c){feedback.tone(current)};button("Preview tone and vibration",c){feedback.tone(current);feedback.vibrate()}}
        button("Restore default phase tones"){Signals.events.forEach{store.settings.remove("tone_$it")};store.save();toneSettings()};button("Settings"){screen="main";tab="Settings";renderMain()}
    }
    private fun cuePanel(){val box=LinearLayout(this).apply{orientation=1;setPadding(dp(22),dp(10),dp(22),dp(16))};toggle(box,"Phase sound","sound",true);toggle(box,"Vibration","haptic",true);slider(box,"App brightness","brightness",12,2){applyBrightness()};button("Test current phase",box){feedback.signal(PracticeService.live?.engine?.phase?.kind?.name ?:"REST")};AlertDialog.Builder(this).setTitle("Session settings").setView(box).setPositiveButton("Close",null).show()}
    private fun learn(){heading("Guide","Practice instructions, background and sources.");Knowledge.articles.forEach{a->val c=panel();label(c,a.category,12f,P.accent);gap(6,c);label(c,a.title,21f,P.text,true);gap(7,c);label(c,a.summary,13f,P.muted);button("Read",c){read(a)}}}
    private fun read(a:Knowledge.Article){screen="reading";base(false);button("Back"){screen="main";renderMain()};gap(16);heading(a.title,a.summary);a.body.split("\n\n").forEach{label(page,it,16f);gap(18)};label(page,"Sources",17f,P.text,true);a.sources.forEach{(t,u)->button(t){startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(u)))}}}
    private fun pulseDialog(save:(Int)->Unit){val b=LinearLayout(this).apply{orientation=1;setPadding(dp(22),dp(12),dp(22),dp(16))};label(b,"Enter a pulse reading or count your wrist pulse for 30 seconds while breathing normally.",14f,P.muted);val value=field(b,"Pulse in bpm","",true);val status=label(b,"",14f);var count=0;var running=false;var active=true;var end=0L;val tap=button("Count beat",b){if(running){count++;status.text="$count beats"}};tap.isEnabled=false
        val counter=object:Runnable{override fun run(){if(!active || !running)return;val left=((end-SystemClock.elapsedRealtime()+999)/1000).coerceAtLeast(0);status.text="$left s remaining · $count beats";if(left==0L){running=false;tap.isEnabled=false;value.setText((count*2).toString());status.text="$count beats × 2 = ${count*2} bpm";feedback.vibrate()}else ui.postDelayed(this,200)}}
        button("Start 30-second count",b){ui.removeCallbacks(counter);count=0;running=true;end=SystemClock.elapsedRealtime()+30000;tap.isEnabled=true;ui.post(counter)}
        val dlg=AlertDialog.Builder(this).setTitle("Pulse").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dlg.setOnShowListener{dlg.getButton(-1).setOnClickListener{val n=value.text.toString().toIntOrNull();if(running)value.error="Complete the count first"else if(n==null || n !in 20..250)value.error="Enter 20–250 bpm"else{safe{save(n)};dlg.dismiss()}}};dlg.setOnDismissListener{active=false;ui.removeCallbacks(counter)};dlg.show()
    }
    private fun walkSetup(){check(PracticeService.live==null){"Finish the current session first"};screen="walking";base(false);heading("Walking practice","Count comfortable breath-pause steps on safe, level ground.");note("End at the first urge to breathe, even before the step reference. Recover fully between rounds. Avoid holds near traffic, water, stairs or heights, and if your health makes them unsuitable.");val target=field(page,"Step reference (1–50)",reference.toString(),true);button("Start walking",primary=true){val n=target.text.toString().toIntOrNull();require(n!=null && n in 1..50){"Enter 1–50 steps"};reference=n;walking=true;holding=false;steps=0;totalSteps=0;rounds.clear();walkStart=SystemClock.elapsedRealtime();walkDate=System.currentTimeMillis();walkId=Store.id();checkpointWalk();startSensor();renderWalk()};button("Back"){screen="main";renderMain()}}
    private fun renderWalk(){screen="walking";base(false);heading(if(holding)"Walking pause"else"Recovery");label(page,if(holding)"Steps in this round"else"Total hold steps",13f,P.muted);stepLabel=label(page,"0",62f,P.text,true);walkTime=label(page,"",16f,P.muted);label(page,"${if(sensor)"Phone step detector"else"Manual steps"} · reference $reference",13f,P.muted);gap(16)
        if(holding){button("End hold · breathe now",primary=true){endHold()}.minHeight=dp(80);if(!sensor)button("Count step"){addStep()};note("Breathe at the first urge. The step reference is a limit, not a target to push through.")}
        else{note("Walk and breathe normally until comfortable. Begin a brief pause after a normal exhalation when ready.");button("Begin walking pause",primary=true){holding=true;steps=0;holdStart=SystemClock.elapsedRealtime();renderWalk()};button(if(sensor)"Use manual steps"else"Try phone step detector"){if(sensor){stopSensor();walkSource="Manual"}else startSensor();renderWalk()};button("Change step reference"){val b=LinearLayout(this).apply{orientation=1;setPadding(dp(20),dp(8),dp(20),dp(8))};val f=field(b,"1–50 steps",reference.toString(),true);AlertDialog.Builder(this).setTitle("Step reference").setView(b).setNegativeButton("Cancel",null).setPositiveButton("Set"){_,_->val n=f.text.toString().toIntOrNull();if(n!=null && n in 1..50){reference=n;renderWalk()}else toast("Enter 1–50 steps")}.show()}}
        if(rounds.isNotEmpty()){val c=panel();label(c,"Rounds",18f,P.text,true);rounds.forEachIndexed{i,w->label(c,"${i+1}: ${w.steps} steps · ${"%.1f".format(w.seconds)} s · ${w.source}",13f,P.muted)}};button("Finish and save"){finishWalk()}
    }
    private fun startSensor(){sensor=false;walkSource="Manual";val manager=getSystemService(SENSOR_SERVICE) as SensorManager;val detector=manager.getDefaultSensor(Sensor.TYPE_STEP_DETECTOR);if(detector==null){toast("Step detector unavailable. Manual counting is selected.");return};if(Build.VERSION.SDK_INT>=29 && checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(arrayOf(Manifest.permission.ACTIVITY_RECOGNITION),41);return};sensor=manager.registerListener(this,detector,SensorManager.SENSOR_DELAY_NORMAL);walkSource=if(sensor)"Step detector"else"Manual"}
    private fun stopSensor(){(getSystemService(SENSOR_SERVICE) as SensorManager).unregisterListener(this);sensor=false}
    override fun onRequestPermissionsResult(code:Int,permissions:Array<out String>,results:IntArray){super.onRequestPermissionsResult(code,permissions,results);if(code==41 && walking){if(results.firstOrNull()==PackageManager.PERMISSION_GRANTED)startSensor()else toast("Manual step counting selected");renderWalk()}}
    override fun onAccuracyChanged(sensor:Sensor?,accuracy:Int){}
    override fun onSensorChanged(event:SensorEvent?){if(event?.sensor?.type==Sensor.TYPE_STEP_DETECTOR && walking && holding)addStep()}
    private fun addStep(){if(!holding)return;steps++;totalSteps++;stepLabel?.text=steps.toString();if(steps>=reference){endHold();toast("Step reference reached. Breathe normally.")}}
    private fun walkEntry(status:String)=Entry(walkId,walkDate,"Walking practice",((SystemClock.elapsedRealtime()-walkStart)/1000).toInt(),status,walks=rounds.toList(),comment="Walking holds are separate from seated CP measurements.",context="After walking")
    private fun checkpointWalk(){safe{Store.write(store.active,Codec.entry(walkEntry("Interrupted")).toString())}}
    private fun endHold(){if(!holding)return;rounds.add(WalkValue(steps,(SystemClock.elapsedRealtime()-holdStart)/1000.0,walkSource));holding=false;checkpointWalk();feedback.signal("RECOVER");renderWalk()}
    private fun finishWalk(){if(!walking)return;if(holding){rounds.add(WalkValue(steps,(SystemClock.elapsedRealtime()-holdStart)/1000.0,walkSource));holding=false};walking=false;stopSensor();safe{store.upsert(walkEntry("Completed"));store.active.delete()};feedback.signal("END");screen="main";tab="Diary";renderMain();toast("Walking session saved")}
    private fun exportDialog(){if(store.entries.isEmpty()){toast("The diary is empty");return};AlertDialog.Builder(this).setTitle("Export diary").setItems(arrayOf("Share or email CSV table","Share or email images","Save CSV table")){_,n->safe{when(n){0->share(store.entries,false);1->share(store.entries,true);else->{exportPending=Exports.csv(store.entries).toByteArray(Charsets.UTF_8);createDocument("Upekkha-diary.csv","text/csv")}}}}.show()}
    private fun share(entries:List<Entry>,images:Boolean){val copy=entries.toList();val progress=ProgressDialog(this).apply{setMessage(if(images)"Preparing images…"else"Preparing table…");setCancelable(false);show()};Thread{try{val files=if(images)Exports.images(this,copy)else listOf(Exports.file(this,"Upekkha-diary-${System.currentTimeMillis()}.csv",Exports.csv(copy).toByteArray(Charsets.UTF_8)));runOnUiThread{if(!isFinishing && !isDestroyed){progress.dismiss();safe{val uris=ArrayList(files.map{ExportProvider.uri(it.name)});val intent=Intent(if(uris.size>1)Intent.ACTION_SEND_MULTIPLE else Intent.ACTION_SEND).apply{type=if(images)"image/png"else"text/csv";putExtra(Intent.EXTRA_SUBJECT,"Upekkhā diary");putExtra(Intent.EXTRA_TEXT,"Breathing practice diary. Excluded CP measurements are marked.");if(uris.size>1)putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris)else putExtra(Intent.EXTRA_STREAM,uris.first());clipData=ClipData.newRawUri("Diary",uris.first()).apply{uris.drop(1).forEach{addItem(ClipData.Item(it))}};addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)};startActivity(Intent.createChooser(intent,"Send diary"))}}}}catch(e:Exception){runOnUiThread{if(!isFinishing && !isDestroyed){progress.dismiss();toast("Export failed: ${e.message}")}}}}.start()}
    private fun createDocument(name:String,mime:String){exportPending?.let{File(cacheDir,"pending-document.bin").writeBytes(it)};startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(mime).putExtra(Intent.EXTRA_TITLE,name),71)}
    override fun onActivityResult(code:Int,result:Int,data:Intent?){super.onActivityResult(code,result,data);if(result!=RESULT_OK)return;val uri=data?.data ?:return;safe{when(code){71->{val cache=File(cacheDir,"pending-document.bin");val bytes=exportPending ?:if(cache.exists())cache.readBytes()else error("Please export again");contentResolver.openOutputStream(uri,"wt")?.use{it.write(bytes)} ?:error("Could not open destination");cache.delete();exportPending=null;toast("File saved")};72->{val bytes=contentResolver.openInputStream(uri)?.use{input->val out=java.io.ByteArrayOutputStream();val b=ByteArray(8192);while(out.size()<=12000000){val n=input.read(b,0,min(b.size,12000001-out.size()));if(n<=0)break;out.write(b,0,n)};out.toByteArray()} ?:error("Could not open backup");require(bytes.size<=12000000){"Backup exceeds 12 MB"};val raw=bytes.toString(Charsets.UTF_8);val v=Codec.parse(raw);ask("Merge backup?","${v.first.size} entries and ${v.second.size} protocols. Missing IDs and saved preferences are imported; existing entries are kept."){val n=store.restore(raw);toast("Restored ${n.first} entries and ${n.second} protocols");renderMain()}}}}}
    private fun welcome(){AlertDialog.Builder(this).setTitle("Before practice").setMessage("Keep breathing exercises gentle. Stop for dizziness, faintness, chest pain, worsening wheeze, distress or unusual breathlessness.\n\nDo not hold your breath in water, while driving, or where a fall could cause injury. Seek individual medical advice if pregnant, under 18, or affected by fainting, seizures or a significant medical condition. Keep prescribed treatment and your asthma action plan.\n\nCP is a personal practice observation. It does not diagnose illness or measure CO₂.").setPositiveButton("Continue"){_,_->safe{store.settings.put("safetyAccepted",true);store.save()}}.setNeutralButton("Safety information"){_,_->read(Knowledge.articles.first{it.category=="Safety"})}.show()}
}
